<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>2048</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    background: #0f0f1a;
    color: #e0e0ff;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  }
  #score {
    font-size: 1.5rem;
    margin-bottom: 1rem;
  }
  #board {
    display: grid;
    grid-template-columns: repeat(4, 6rem);
    grid-template-rows: repeat(4, 6rem);
    gap: 0.5rem;
    background: #1a1a2e;
    padding: 0.75rem;
    border-radius: 0.75rem;
    box-shadow: 0 8px 32px rgba(0,0,0,0.6);
  }
  .cell {
    width: 6rem;
    height: 6rem;
    background: #16213e;
    border-radius: 0.4rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    font-weight: bold;
    color: #ffffff;
  }
  .tile-2 { color: #f5e663; }
  .tile-4 { color: #f5d547; }
  .tile-8 { color: #f5c047; }
  .tile-16 { color: #f5a947; }
  .tile-32 { color: #f59547; }
  .tile-64 { color: #f58247; }
  .tile-128 { font-size: 1.7rem; color: #f57047; }
  .tile-256 { font-size: 1.7rem; color: #f55e47; }
  .tile-512 { font-size: 1.7rem; color: #f54a47; }
  .tile-1024 { font-size: 1.4rem; color: #f53a47; }
  .tile-2048 { font-size: 1.4rem; color: #f52a47; }
  .tile-high { font-size: 1.2rem; color: #f51a47; }
  #reset {
    margin-top: 1.25rem;
    padding: 0.5rem 1.25rem;
    font-size: 1rem;
    background: #0f3460;
    color: #e0e0ff;
    border: none;
    border-radius: 0.4rem;
    cursor: pointer;
  }
  #reset:hover { background: #144a7d; }
</style>
</head>
<body>
  <div id="score">Score: 0</div>
  <div id="board"></div>
  <button id="reset">New Game</button>

  <script>
    (function () {
      const SIZE = 4;
      let board = [];
      let score = 0;
      let cells = [];

      function initBoard() {
        board = Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
        score = 0;
      }

      function countEmpty() {
        let count = 0;
        for (let r = 0; r < SIZE; r++) {
          for (let c = 0; c < SIZE; c++) {
            if (board[r][c] === 0) count++;
          }
        }
        return count;
      }

      function randomEmpty() {
        const empties = [];
        for (let r = 0; r < SIZE; r++) {
          for (let c = 0; c < SIZE; c++) {
            if (board[r][c] === 0) empties.push([r, c]);
          }
        }
        if (empties.length === 0) return null;
        return empties[Math.floor(Math.random() * empties.length)];
      }

      function spawnTile() {
        const pos = randomEmpty();
        if (!pos) return;
        board[pos[0]][pos[1]] = Math.random() < 0.9 ? 2 : 4;
      }

      function render() {
        for (let r = 0; r < SIZE; r++) {
          for (let c = 0; c < SIZE; c++) {
            const tile = cells[r][c];
            const value = board[r][c];
            tile.textContent = value === 0 ? "" : value;
            tile.className = "cell";
            if (value > 0) {
              tile.classList.add("tile-" + value);
              if (value >= 4096) tile.classList.add("tile-high");
            }
          }
        }
        document.getElementById("score").textContent = "Score: " + score;
      }

      function slideRowLeft(row) {
        // Compact non-zero values to the left
        const filtered = row.filter(v => v !== 0);
        const result = [];
        let i = 0;
        let merged = false;
        while (i < filtered.length) {
          if (i + 1 < filtered.length && filtered[i] === filtered[i + 1]) {
            result.push(filtered[i] * 2);
            score += filtered[i] * 2;
            i += 2;
            merged = true;
          } else {
            result.push(filtered[i]);
            i++;
          }
        }
        while (result.length < SIZE) result.push(0);
        return result;
      }

      function moveLeft() {
        let moved = false;
        const newBoard = [];
        for (let r = 0; r < SIZE; r++) {
          const oldRow = board[r];
          const newRow = slideRowLeft(oldRow);
          for (let c = 0; c < SIZE; c++) {
            if (oldRow[c] !== newRow[c]) moved = true;
          }
          newBoard.push(newRow);
        }
        board = newBoard;
        return moved;
      }

      function moveRight() {
        let moved = false;
        const newBoard = [];
        for (let r = 0; r < SIZE; r++) {
          const reversed = board[r].slice().reverse();
          const slid = slideRowLeft(reversed);
          const newRow = slid.slice().reverse();
          for (let c = 0; c < SIZE; c++) {
            if (board[r][c] !== newRow[c]) moved = true;
          }
          newBoard.push(newRow);
        }
        board = newBoard;
        return moved;
      }

      function moveUp() {
        let moved = false;
        const newBoard = Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
        for (let c = 0; c < SIZE; c++) {
          const col = [];
          for (let r = 0; r < SIZE; r++) col.push(board[r][c]);
          const newCol = slideRowLeft(col);
          for (let r = 0; r < SIZE; r++) {
            newBoard[r][c] = newCol[r];
            if (newBoard[r][c] !== board[r][c]) moved = true;
          }
        }
        board = newBoard;
        return moved;
      }

      function moveDown() {
        let moved = false;
        const newBoard = Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
        for (let c = 0; c < SIZE; c++) {
          const col = [];
          for (let r = 0; r < SIZE; r++) col.push(board[r][c]);
          const reversed = col.reverse();
          const slid = slideRowLeft(reversed);
          const newCol = slid.slice().reverse();
          for (let r = 0; r < SIZE; r++) {
            newBoard[r][c] = newCol[r];
            if (newBoard[r][c] !== board[r][c]) moved = true;
          }
        }
        board = newBoard;
        return moved;
      }

      function doMove(direction) {
        let moved;
        if (direction === "left") moved = moveLeft();
        else if (direction === "right") moved = moveRight();
        else if (direction === "up") moved = moveUp();
        else if (direction === "down") moved = moveDown();
        else return false;
        if (moved) spawnTile();
        render();
        return moved;
      }

      // Build board cells
      const boardEl = document.getElementById("board");
      cells = Array.from({ length: SIZE }, () => []);
      for (let r = 0; r < SIZE; r++) {
        for (let c = 0; c < SIZE; c++) {
          const cell = document.createElement("div");
          cell.className = "cell";
          cells[r][c] = cell;
          boardEl.appendChild(cell);
        }
      }

      // Window API
      window.game = {
        size: SIZE,
        reset: function () {
          initBoard();
          spawnTile();
          spawnTile();
          render();
        },
        move: function (direction) {
          return doMove(direction);
        },
        board: function () {
          return board.map(row => row.slice());
        },
        setBoard: function (arr) {
          board = arr.map(row => row.slice());
          score = 0;
          render();
        },
        score: function () {
          return score;
        }
      };

      // Keyboard controls
      document.addEventListener("keydown", function (e) {
        let dir = null;
        switch (e.key) {
          case "ArrowLeft": dir = "left"; break;
          case "ArrowRight": dir = "right"; break;
          case "ArrowUp": dir = "up"; break;
          case "ArrowDown": dir = "down"; break;
        }
        if (dir) {
          e.preventDefault();
          doMove(dir);
        }
      });

      document.getElementById("reset").addEventListener("click", function () {
        game.reset();
      });

      // Start a new game on load
      game.reset();
    })();
  </script>
</body>
</html>
